import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { resolve } from "node:path";
import { BaseError, UserRejectedRequestError } from "viem";
import { describe, expect, it, vi } from "vitest";
import { humanizeError } from "./errors";
import { canonicalJson, normalizeHash, sha256File, sha256Text } from "./hash";
import { hashPair, leafOf, merkleRoot, proofsForAll, verifyProof } from "./merkle";
import { verifyOnChain } from "./verify";
import type { ReadClient } from "./verify";

// Cross-language vectors generated by contracts/scripts/gen-vectors.ts and also asserted by the contract and backend tests.
const V = JSON.parse(readFileSync(resolve(process.cwd(), "../contracts/test/vectors.json"), "utf8"));

const nodeSha = (b: Uint8Array) => "0x" + createHash("sha256").update(b).digest("hex");

describe("document fingerprints", () => {
  it("match the shared SHA-256 vectors", async () => {
    for (const v of V.sha256) expect(await sha256File(new Blob([v.input_utf8]))).toBe(v.digest);
    expect(sha256Text("abc")).toBe(V.sha256[1].digest);
  });

  it("depend only on the bytes: renaming a file changes nothing, one flipped bit changes everything", async () => {
    const bytes = new Uint8Array(1000).map((_, i) => i % 251);
    const a = await sha256File(new File([bytes], "report-final.pdf"));
    const b = await sha256File(new File([bytes], "completely-different.docx", { type: "text/plain", lastModified: 1 }));
    expect(a).toBe(b);
    const flipped = bytes.slice();
    flipped[500] ^= 1;
    expect(await sha256File(new File([flipped], "report-final.pdf"))).not.toBe(a);
  });

  it("stream large files in chunks and still equal the one-shot digest (crossing the 4 MiB boundary)", async () => {
    const bytes = new Uint8Array(9 * 1024 * 1024 + 17).map((_, i) => (i * 31) % 256);
    const progress: number[] = [];
    const h = await sha256File(new Blob([bytes]), (p) => progress.push(p));
    expect(h).toBe(nodeSha(bytes));
    expect(progress.at(-1)).toBe(1);
    expect(progress.length).toBeGreaterThan(2);
  });

  it("can be cancelled", async () => {
    const ctl = new AbortController();
    ctl.abort();
    await expect(sha256File(new Blob([new Uint8Array(10)]), undefined, ctl.signal)).rejects.toThrow(/cancel/i);
  });

  it("normalise to the lowercase 0x form and reject anything else", () => {
    const h = "0x" + "ab".repeat(32);
    expect(normalizeHash(h.toUpperCase().replace("0X", "0x"))).toBe(h);
    expect(normalizeHash("ab".repeat(32))).toBe(h);
    expect(normalizeHash(` ${h} `)).toBe(h);
    for (const bad of ["", "0x", "0x" + "ab".repeat(31), "0x" + "zz".repeat(32), "hello"]) expect(normalizeHash(bad)).toBeNull();
  });
});

describe("canonical metadata JSON", () => {
  it("is byte-identical to the shared vectors (including unicode, escapes and nesting)", () => {
    for (const m of V.metadata) {
      expect(canonicalJson(m.value)).toBe(m.canonical);
      expect(sha256Text(m.canonical)).toBe(m.sha256);
    }
  });
});

describe("Merkle batches", () => {
  it("reproduce the roots and proofs the contract is tested against", () => {
    for (const v of V.merkle) {
      expect(merkleRoot(v.hashes)).toBe(v.root);
      expect(proofsForAll(v.hashes)).toEqual(v.proofs);
      v.hashes.forEach((h: string, i: number) => expect(verifyProof(v.proofs[i], v.root, h)).toBe(true));
    }
  });

  it("reject wrong proofs, wrong documents and inner nodes posing as documents", () => {
    const v = V.merkle[3]; // 4 leaves
    expect(verifyProof(v.proofs[0], v.root, v.hashes[1])).toBe(false);
    expect(verifyProof(v.proofs[0].slice(0, 1), v.root, v.hashes[0])).toBe(false);
    const inner = hashPair(leafOf(v.hashes[0]), leafOf(v.hashes[1]));
    expect(verifyProof([hashPair(leafOf(v.hashes[2]), leafOf(v.hashes[3]))], v.root, inner)).toBe(false);
    expect(() => merkleRoot([])).toThrow();
  });
});

describe("verifyOnChain (reads the contract, never the API)", () => {
  const H = "0x" + "11".repeat(32);
  const doc = (status: number, extra = {}) => ({ status, issuer: "0xAbC0000000000000000000000000000000000001", issuerAuthorized: true, documentId: "0x" + "22".repeat(32), version: 2, latestVersion: 3, docType: 5,
    metadataHash: "0x" + "00".repeat(32), registeredAt: 1_700_000_000n, expiresAt: 0n, revokedAt: 0n, revokedBy: "0x" + "00".repeat(20), reasonHash: "0x" + "00".repeat(32), ...extra });
  const client = (impl: (fn: string) => unknown): ReadClient => ({ readContract: vi.fn(async ({ functionName }) => impl(functionName)) });

  it("maps a valid registration to VERIFIED with its facts", async () => {
    const r = await verifyOnChain(client(() => doc(1)), "0xreg", H);
    expect(r).toMatchObject({ verdict: "verified", kind: "document", issuer: "0xabc0000000000000000000000000000000000001", version: 2, latestVersion: 3, documentType: "audit_report", registeredAt: 1_700_000_000, revokedAt: null, expiresAt: null });
  });

  it("maps revoked and expired", async () => {
    expect((await verifyOnChain(client(() => doc(2, { revokedAt: 1_700_000_500n })), "0xreg", H))).toMatchObject({ verdict: "revoked", revokedAt: 1_700_000_500 });
    expect((await verifyOnChain(client(() => doc(3, { expiresAt: 1_700_000_100n })), "0xreg", H)).verdict).toBe("expired");
  });

  it("maps an unknown fingerprint to NOT VERIFIED without consulting proofs it was not given", async () => {
    const r = await verifyOnChain(client(() => doc(0)), "0xreg", H);
    expect(r).toMatchObject({ verdict: "not_verified", kind: null, issuer: null });
  });

  it("checks every proof hint against the contract and only trusts the contract's answer", async () => {
    const batch = (included: boolean, status = 1) => ({ included, status, issuer: "0xAbC0000000000000000000000000000000000001", issuerAuthorized: true, registeredAt: 5n, revokedAt: status === 2 ? 9n : 0n, merkleRoot: "0x" + "33".repeat(32) });
    const impl = (included: boolean, status?: number) => client((fn) => (fn === "verifyDocument" ? doc(0) : batch(included, status)));
    const hints = async () => [{ batch_id: 4, merkle_root: "0x" + "33".repeat(32), leaf_index: 0, proof: ["0x" + "44".repeat(32)] }];
    expect(await verifyOnChain(impl(true), "0xreg", H, hints)).toMatchObject({ verdict: "verified", kind: "batch", batchId: 4 });
    expect((await verifyOnChain(impl(true, 2), "0xreg", H, hints)).verdict).toBe("revoked");
    expect((await verifyOnChain(impl(false), "0xreg", H, hints)).verdict).toBe("not_verified"); // a bogus hint proves nothing
  });

  it("propagates RPC failures instead of reporting NOT VERIFIED", async () => {
    await expect(verifyOnChain({ readContract: async () => { throw new Error("network down"); } }, "0xreg", H)).rejects.toThrow("network down");
  });
});

describe("humanizeError", () => {
  it("explains wallet rejections, contract reverts and network failures", () => {
    expect(humanizeError(new UserRejectedRequestError(new Error("no")))).toMatch(/rejected/i);
    expect(humanizeError({ code: 4001, message: "User rejected the request" })).toMatch(/rejected/i);
    expect(humanizeError(new Error("execution reverted: AlreadyRegistered(0x12)"))).toMatch(/already been registered/);
    expect(humanizeError(new Error("reverted with NotAuthorizedIssuer"))).toMatch(/not an authorised issuer/);
    expect(humanizeError(new Error("HTTP request failed. Details: fetch failed"))).toMatch(/Could not reach the network/);
    expect(humanizeError(new Error("insufficient funds for gas"))).toMatch(/no native coin/);
    expect(humanizeError(new BaseError("weird"))).toMatch(/failed/i);
  });
});
